const U=3,G=9.8,TP=U/G,T=2*TP,H=U*U/(2*G);
const f=sdk.format;
function st(t){return {y:U*t-G*t*t/2,v:U-G*t};}
function vs(v){return Math.abs(v)<0.005?'0 m/s':(v>0?'+':'\u2212')+f(Math.abs(v),2)+' m/s';}
function kin(id,x,y,v,k,lx,aLen,aOn,role){
  const o=[sdk.circle(id+'b',x,y,20,{role:role||'input'})];
  const L=v*k;
  if(Math.abs(L)<4)o.push(sdk.circle(id+'v',x-18,y,8,{role:'output'}));
  else o.push(sdk.arrow(id+'v',x-18,y,x-18,y-L,{role:'output'}));
  if(aOn)o.push(sdk.arrow(id+'a',x+18,y,x+18,y+aLen,{role:'warning'}));
  o.push(sdk.text(id+'t',lx,y-10,'v = '+vs(v),{align:'start',role:'output'}));
  if(aOn)o.push(sdk.text(id+'g',lx,y+20,'a = 9.8 m/s\u00b2 \u2193',{align:'start',role:'warning'}));
  return o;
}
export function evaluate({time}){
  const t=sdk.clamp(time||0,0,T);const o=[];
  o.push(sdk.text('h1',40,26,'Three moments around the top (up positive)',{align:'start'}));
  [[-0.1,'\u22120.10 s'],[0,'Top 0 s'],[0.1,'+0.10 s']].forEach(([d,lab],i)=>{
    const cx=150+i*330,s=st(TP+d),y=110+(H-s.y)*600;
    o.push(sdk.box('p'+i,cx-110,40,220,190,{role:'neutral'}),sdk.text('pl'+i,cx,64,lab,{align:'middle'}));
    o.push(...kin('s'+i,cx-60,y,s.v,40,cx-25,36,true));
    if(i<2)o.push(sdk.arrow('pa'+i,cx+114,135,cx+216,135),sdk.text('pc'+i,cx+165,254,'Velocity changes by 0.98 m/s downward',{align:'middle'}));
  });
  const Y0=680,K=650,ya=Y0-H*K;
  o.push(sdk.text('h2',40,292,'Live: two lanes on one height scale',{align:'start'}));
  o.push(sdk.line('ax',120,Y0,120,ya-24),sdk.text('axl',120,ya-32,'height (m)',{align:'middle'}));
  [0,0.2,0.4].forEach((h,i)=>o.push(sdk.text('tk'+i,88,Y0-h*K+4,f(h,1),{align:'middle'})));
  o.push(sdk.text('ln1',380,316,'Toss',{align:'middle'}),sdk.text('ln2',620,316,'Drop',{align:'middle'}));
  o.push(sdk.line('gl',140,Y0,920,Y0),sdk.line('gu',140,ya,920,ya));
  o.push(sdk.text('gll',800,Y0-8,'launch height',{align:'start'}),sdk.text('gul',800,ya-8,'apex level',{align:'start'}));
  const s=st(t);
  o.push(...kin('ts',380,Y0-s.y*K,s.v,30,440,40,true,'input'));
  const rel=t>=TP-1e-4,dt=Math.max(0,t-TP),yd=rel?H-G*dt*dt/2:H,vd=rel?-G*dt:0;
  o.push(...kin('dr',620,Y0-yd*K,vd,30,680,40,rel,'learner'));
  const yb=ya+11;
  o.push(sdk.line('gt1',596,yb,rel?596:620,rel?yb+14:yb,{role:'neutral'}),sdk.line('gt2',644,yb,rel?644:620,rel?yb+14:yb,{role:'neutral'}));
  o.push(sdk.text('gtl',560,ya-14,rel?'Open':'Held',{align:'middle'}));
  const q={tTop:t-TP,vToss:s.v,vDrop:vd,hToss:s.y};
  return {frame:sdk.frame(o,{width:960,height:840,readouts:Object.keys(q).map(k=>({id:k,value:q[k]}))}),quantities:q};
}
